use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Body {
    Text { text: String },
    File { file_id: String },
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SendMessage {
    /// UUID generated by the sender; keep it unchanged on retry.
    pub id: String,
    pub to: String,
    pub body: Body,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Message {
    pub id: String,
    pub from: String,
    pub to: String,
    pub body: Body,
    pub created_at: i64,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ClientEvent {
    Send {
        message: SendMessage,
    },
    /// Recipient acknowledges a message; sender acknowledges a delivered event.
    Ack {
        id: String,
    },
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ServerEvent {
    Ready { device_id: String },
    Accepted { id: String },
    Message { message: Message },
    Delivered { id: String },
    Error { code: u16, message: String },
}

#[derive(Debug, Serialize, Deserialize)]
pub struct FileInfo {
    pub id: String,
    pub name: String,
    pub size: u64,
    pub sha256: String,
    pub expires_at: i64,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct DirectDevice {
    pub id: String,
    pub alias: String,
    pub fingerprint: String,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum DirectRequest {
    Register {
        alias: String,
        certificate: String,
        signature: String,
    },
    Signal {
        to: String,
        session: String,
        offer: bool,
        sdp: String,
    },
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum DirectEvent {
    Challenge {
        device_id: String,
        nonce: String,
    },
    Devices {
        devices: Vec<DirectDevice>,
    },
    Signal {
        from: DirectDevice,
        session: String,
        offer: bool,
        sdp: String,
    },
    Rejected {
        session: String,
    },
}

pub fn identity_proof(device: &str, nonce: &str, alias: &str, fingerprint: &str) -> Vec<u8> {
    format!("AntifyBot p2p identity v1\n{device}\n{nonce}\n{fingerprint}\n{alias}").into_bytes()
}

pub fn direct_sdp(sdp: &str) -> bool {
    sdp.len() <= 48 * 1024
        && sdp.lines().filter(|line| line.starts_with("m=")).eq(sdp
            .lines()
            .filter(|line| line.starts_with("m=application ")))
        && sdp
            .lines()
            .filter(|line| line.starts_with("a=candidate:"))
            .all(|line| {
                matches!(
                    line.split_ascii_whitespace().nth(7),
                    Some("host" | "srflx" | "prflx")
                )
            })
}

/// Signal marker for a paired HTTPS data connection.
pub const HTTPS_RELAY: &str = "antify-https-relay-v1";
